UPDATE decision_nodes SET data = '{"type":"info","module":1,"title":"Cervical Artery Dissection","body":"**Carotid or vertebral artery dissection** — intimal tear with intramural hematoma causing stenosis/occlusion or pseudoaneurysm.\n\n**Key Context: Strangulation**\n> Non-fatal strangulation is a MAJOR risk factor for cervical artery dissection.\n> Up to 50% of intimate partner violence victims experience strangulation.\n> Symptoms may be delayed 24-72 hours or more.\n\n**Mechanism:** Compression and hyperextension of neck → shearing forces on arteries → intimal tear.\n\n**Mortality:** Strangulation can be fatal with as little as 10 seconds of pressure. [1][2]","citation":[1,2],"next":"cad-mechanism","calculatorLinks":[{"id":"nihss-calculator","label":"NIH Stroke Scale"},{"id":"strangulation-danger","label":"Strangulation Danger Score"},{"id":"cervical-artery-dissection","label":"Neck Injury Assessment","kind":"tree","node":"cad-strangulation"},{"id":"ipv-safety-plan","label":"IPV Safety Planning"}],"summary":"Non-fatal strangulation is a major risk factor — symptoms may delay 24-72 hours"}'::jsonb
