-- Node: cspine-sci-resuscitation (4 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":7,"title":"SCI Resuscitation","body":"**Spinal Cord Injury Resuscitation**\n\n**Blood Pressure Targets:**\n\n| Parameter | Target | Duration |\n|-----------|--------|----------|\n| **MAP** | **75-95 mmHg** | 3-7 days |\n| SBP | 90-100 mmHg minimum | Continuous |\n\n**Evidence:** 2024 AO Spine/Praxis CPG *suggests* 75-95 mmHg for 3-7 days — a deliberately WIDER window than the 2013 AANS/CNS 85-90 mmHg figure, which was Level III and practically unmaintainable. Evidence is observational only; both MAP <75 and MAP >95 associate with worse outcomes. Treat a MAP of 82 as on target, not a failure. Evidence was insufficient for any SCPP target. See MAP Goals for the full 2013-vs-2024 comparison [20].\n\n**Vasopressor:**\n⚠️ **Norepinephrine is the consensus choice** (α + β activity) — but NO study in the 2024 guideline evaluated norepinephrine for safety or effectiveness in SCI. This is expert practice, not guideline-supported evidence.\n\n**Neurogenic Shock:**\n• Hypotension + bradycardia (distinguish from hypovolemic)\n• Initial: IV fluids (often sufficient)\n• ❌ **Avoid phenylephrine alone** (pure α1 → reflex bradycardia worsens)\n• For bradycardia: Atropine or glycopyrrolate\n\n**Airway:**\n• C2-C4 injuries: High risk for respiratory failure\n• Monitor for delayed deterioration (edema peaks days 3-6)\n• Consider early tracheostomy [1][15]","citation":[1,15,20],"next":"cspine-steroids","calculatorLinks":[{"id":"sci-map-goals","label":"MAP Goals","kind":"info"}],"summary":"MAP 75-95 mmHg for 3-7 days (2024) — NE by consensus, AVOID phenylephrine alone","safetyLevel":"warning"}'::jsonb
WHERE id = 'cspine-sci-resuscitation' AND tree_id = 'cervical-spine';

