-- Node: hypotension-pocus (2 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":2,"title":"RUSH Exam — Bedside POCUS","body":"**RUSH (Rapid Ultrasound in Shock) — HI-MAP:**\n\n**H — Heart:**\n• EF (hyperdynamic vs depressed)\n• Pericardial effusion / tamponade\n• RV dilatation (D-sign) → PE\n• Wall motion abnormalities → MI\n\n**I — IVC:**\n• <2 cm + >50% collapse → hypovolemic\n• >2 cm + minimal collapse → cardiogenic/obstructive\n\n**M — Morrison''s / FAST:**\n• Free fluid → hemorrhage, rupture\n\n**A — Aorta:**\n• AAA (>3 cm), dissection flap\n\n**P — Pneumothorax:**\n• Absent lung slide → tension PTX\n\n**Complete RUSH exam in 2-5 minutes.** Improves diagnostic accuracy from 60% to 85%.","citation":[3,4],"next":"hypotension-pocus-findings","calculatorLinks":[{"id":"rush-exam","label":"RUSH Exam Guide","kind":"info"}],"summary":"RUSH = Heart (EF, effusion, RV), IVC (volume), FAST, Aorta, Pneumothorax; 2-5 min, improves dx accuracy to 85%"}'::jsonb
WHERE id = 'hypotension-pocus' AND tree_id = 'hypotension-workup';

-- Node: iih-acetazolamide-dosing (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":4,"title":"Acetazolamide Dosing Protocol","body":"**Starting & Titration:**\n\n**Week 1:** 500 mg PO BID (1 g/day)\n**Week 2:** Increase to 750 mg BID (1.5 g/day) if tolerated\n**Week 3-4:** Increase to 1 g BID (2 g/day)\n**Beyond:** Increase by 250-500 mg/week to max 4 g/day\n\n**IIHTT Tolerability:**\n• 89.5% tolerated ≥1 g/day\n• 44% tolerated max dose (4 g/day)\n• Mean tolerated dose: 2.5 g/day\n\n**Contraindications:**\n❌ Sulfonamide allergy (cross-reactivity possible)\n❌ Severe hepatic/renal disease\n❌ Hypokalemia (uncorrected)\n❌ Adrenal insufficiency\n\n**Monitoring:**\n• BMP at 2-4 weeks (potassium, bicarb)\n• Replete potassium as needed\n• Watch for metabolic acidosis\n\n**Alternatives:**\n• Topiramate 25-100 mg BID (also causes weight loss)\n• Furosemide 20-40 mg daily (less effective)","citation":[10,11],"next":"iih-discharge-mild","calculatorLinks":[{"id":"iih-acetazolamide-guide","label":"Acetazolamide Dosing","kind":"info"}],"summary":"Start 500mg BID, titrate by 250-500mg/week to 2-4g/day. Check BMP in 2-4 weeks. 89% tolerate ≥1g/day per IIHTT.","skippable":true}'::jsonb
WHERE id = 'iih-acetazolamide-dosing' AND tree_id = 'iih';

-- Node: iih-discharge-mild (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"result","module":6,"title":"Discharge — Mild IIH","body":"**Discharge Criteria:**\n✓ Mild visual loss only\n✓ Stable symptoms\n✓ Able to tolerate oral medications\n✓ Close follow-up arranged\n✓ Understands return precautions\n\n**Discharge Medications:**\n• Acetazolamide 500 mg PO BID (titrate to 2-4 g/day)\n• Potassium supplementation PRN (20-40 mEq/day)\n\n**Follow-Up:**\n• Ophthalmology: 1-2 weeks (visual fields, fundus exam)\n• Neurology: 2-4 weeks\n• PCP: 1-2 weeks (BMP check, weight monitoring)\n\n**Patient Education:**\n• Weight loss is critical — 5-10% reduction target\n• Low-sodium diet\n• Expected side effects: tingling, taste changes, fatigue\n• Stop carbonated beverages (taste flat)\n\n**Return Immediately If:**\n• Vision changes (blurring, field loss, double vision)\n• Severe headache not relieved by medication\n• Nausea/vomiting\n• Weakness or numbness","citation":[1,9,10],"recommendation":"DISCHARGE with acetazolamide 500mg BID. Close ophthalmology (1-2 weeks) and neurology (2-4 weeks) follow-up. Weight loss counseling. Return for vision changes.","confidence":"definitive","calculatorLinks":[{"id":"iih-acetazolamide-guide","label":"Acetazolamide Dosing","kind":"info"}]}'::jsonb
WHERE id = 'iih-discharge-mild' AND tree_id = 'iih';

-- Node: larynx-start (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":1,"title":"Laryngeal Trauma","body":"**Rare but lethal** — second most common cause of death in head/neck trauma after intracranial injury [1]\n\n**Incidence:** 1:5,000 to 1:137,000 trauma patients\n\n**CRITICAL WARNING:**\n> **RSI is CONTRAINDICATED** in suspected laryngeal trauma.\n> Paralysis removes spontaneous ventilation. If intubation fails → CICO catastrophe.\n> **Awake tracheostomy is preferred.** [1][2]","citation":[1,2],"next":"larynx-mechanism","calculatorLinks":[{"id":"schaefer-fuhrman","label":"Schaefer-Fuhrman Grading"},{"id":"laryngeal-trauma-airway","label":"Airway Decision Tool","kind":"info"}],"summary":"Laryngeal trauma: airway loss can be rapid and unpredictable — prepare for surgical airway immediately","safetyLevel":"critical"}'::jsonb
WHERE id = 'larynx-start' AND tree_id = 'laryngeal-trauma';

-- Node: hemo-start (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":1,"title":"Massive Hemoptysis","body":"**Life-threatening hemoptysis** = any volume causing:\n• Airway obstruction\n• Respiratory failure\n• Hemodynamic instability\n\n**Volume thresholds (no consensus):**\n• Classic: ≥600 mL/24h\n• Alternative: ≥200 mL/single episode OR ≥100 mL/hr\n• Best mortality predictor: ≥300 mL expectorated [1]\n\n**Key insight:** Adult tracheobronchial space is only 150-200 mL — even \"small\" volumes can cause asphyxiation. **Death is from hypoxemia (drowning), not exsanguination.**\n\n**ABCDE Cognitive Aid**","citation":[1,2,4],"next":"hemo-etiology","calculatorLinks":[{"id":"txa-hemoptysis","label":"TXA Dosing Calculator"},{"id":"massive-hemoptysis","label":"Coagulopathy Reversal","kind":"tree","node":"hemo-coag-reversal"}],"summary":"Life-threatening hemoptysis: death is from drowning, not exsanguination — adult airway holds only 150-200 mL"}'::jsonb
WHERE id = 'hemo-start' AND tree_id = 'massive-hemoptysis';

-- Node: pm-fail-capture (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":2,"title":"Failure to Capture","body":"**⚠️ Pacing spikes present WITHOUT subsequent P wave or QRS. ⚠️**\n\n**Causes:**\n\n**Lead-Related:**\n• Lead dislodgment (most common early post-implant)\n• Lead fracture\n• Lead perforation\n\n**Threshold-Related:**\n• **Hyperkalemia** - K+ >7 mEq/L classic cause\n• Acidosis\n• Hypoxia\n• Ischemia\n• Exit block (fibrosis at lead tip - late)\n\n**Medication-Related:**\n• Flecainide, propafenone\n• Class I antiarrhythmics\n\n**Device:**\n• Battery depletion\n• Output programmed too low\n\n**⚠️ ALWAYS CHECK POTASSIUM ⚠️**\n\n**Acute Management:**\n1. **Check K+** - treat hyperkalemia aggressively\n2. **Increase output** (if able to reprogram)\n3. **Transcutaneous pacing** if unstable\n4. **Magnet** may help (higher output in some devices) [2][5][6]","citation":[2,5,6],"next":"pm-malfunction-management","summary":"Failure to capture: ALWAYS CHECK POTASSIUM (K>7 classic cause), also acidosis/hypoxia/ischemia; treat hyperkalemia aggressively, TCP if unstable","safetyLevel":"critical"}'::jsonb
WHERE id = 'pm-fail-capture' AND tree_id = 'pacemaker';

-- Node: peds-trauma-start (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":1,"title":"Pediatric Trauma: Initial Assessment","body":"[Pediatric Trauma Steps Summary](#/info/peds-trauma-summary) - stepwise approach.\n\n**Children are NOT small adults.** Anatomic and physiologic differences affect injury patterns, clinical presentation, and management.\n\n**Key pediatric differences:**\n- **Airway:** Larger occiput causes neck flexion; smaller airway diameter; anterior/cephalad larynx\n- **Breathing:** Higher metabolic rate = faster desaturation; chest wall more compliant = pulmonary contusion without rib fractures\n- **Circulation:** Higher physiologic reserve = BP maintained until >25-30% blood loss; tachycardia is early sign\n- **Disability:** Fontanelles and open sutures can mask ICP elevation in infants\n- **Exposure:** Large body surface area = rapid heat loss; aggressive temperature management\n\n**Golden principles:**\n1. Use weight-based dosing for ALL medications\n2. Equipment sizing is critical - use Broselow tape or age-based formulas\n3. Maintain high suspicion for non-accidental trauma (NAT)\n4. Involve pediatric surgery/trauma early for moderate-severe injuries [1][2]","citation":[1,2],"next":"peds-trauma-weight","calculatorLinks":[{"id":"broselow-weight","label":"Broselow Weight Estimation"},{"id":"peds-vital-signs","label":"Pediatric Vital Signs by Age","kind":"info"}],"summary":"Children NOT small adults; larger occiput, faster desaturation, BP drops late (>25-30% blood loss); use weight-based dosing for all meds"}'::jsonb
WHERE id = 'peds-trauma-start' AND tree_id = 'peds-trauma';

-- Node: peds-trauma-salter (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":5,"title":"Salter-Harris Classification","body":"**SALTR mnemonic for physeal fractures:**\n\n| Type | Description | Mnemonic | Prognosis |\n|------|-------------|----------|-----------|\n| I | Through physis only | **S**lipped | Good |\n| II | Through physis + metaphysis | **A**bove | Good |\n| III | Through physis + epiphysis (intra-articular) | **L**ower | Guarded |\n| IV | Through metaphysis + physis + epiphysis | **T**hrough | Poor |\n| V | Crush injury to physis | c**R**ush | Poor |\n\n**Management principles:**\n- **Type I & II:** Usually closed reduction, casting. Good prognosis.\n- **Type III & IV:** Often require ORIF. Risk of growth arrest, angular deformity.\n- **Type V:** Diagnosed retrospectively when growth arrest occurs. High risk of deformity.\n\n**Key points:**\n- X-rays may initially appear normal in Type I and V --> clinical diagnosis\n- Compare to contralateral side if uncertain\n- Follow up in 10-14 days if high suspicion with negative initial films\n- Parents should be counseled about risk of growth disturbance in higher grades [11]","citation":[11],"next":"peds-trauma-compartment","calculatorLinks":[{"id":"salter-harris","label":"Salter-Harris Classification Guide","kind":"info"}],"summary":"SALTR: I=Slipped, II=Above, III=Lower (intra-articular), IV=Through, V=cRush; III-V need ORIF and have growth arrest risk","skippable":true}'::jsonb
WHERE id = 'peds-trauma-salter' AND tree_id = 'peds-trauma';

-- Node: preg-trauma-start (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":1,"title":"Pregnancy in Trauma","body":"[Pregnancy Trauma Tools](#/info/preg-trauma-tools) — resuscitative hysterotomy, RhIg calculator, monitoring guide.\n\n**Trauma is the leading non-obstetric cause of maternal death** — affects 6-7% of pregnancies. [1][2]\n\n**GOLDEN RULE: Mother First**\n> The best fetal resuscitation is maternal resuscitation.\n> Fetal survival depends on maternal survival.\n\n**Key physiologic changes:**\n• Blood volume ↑ 50% — can lose 30% before shock signs\n• Cardiac output ↑ 30-50% — heart rate ↑ 15-20 bpm baseline\n• Plasma > RBC expansion → \"physiologic anemia\" (Hgb 11 g/dL normal)\n• IVC compression after 20 weeks → supine hypotension syndrome\n• Uterine blood flow = 500-700 mL/min at term — massive hemorrhage risk\n\n**Fetus is first to suffer:** Blood shunted away from uterus to preserve maternal vital organs. [1][2][3]","citation":[1,2,3],"next":"preg-trauma-ga","calculatorLinks":[{"id":"gestational-age","label":"Gestational Age"},{"id":"rhig-calculator","label":"RhIg Dosing"},{"id":"resuscitative-hysterotomy","label":"Resuscitative Hysterotomy","kind":"tree"}],"summary":"Mother first — fetal survival depends on maternal survival. Blood volume ↑50%, can lose 30% before shock.","safetyLevel":"critical"}'::jsonb
WHERE id = 'preg-trauma-start' AND tree_id = 'pregnancy-trauma';

-- Node: preg-trauma-cardiac-arrest (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":5,"title":"Cardiac Arrest in Pregnancy","body":"**Modified ACLS with pregnancy-specific considerations:**\n\n**KEY MODIFICATIONS:**\n\n1. **Manual left uterine displacement** — assign team member\n2. **Defibrillation** — same doses, remove fetal monitors\n3. **Chest compressions** — may need slightly higher on sternum\n4. **IV access** — above diaphragm preferred (IVC compression)\n5. **Intubation** — smaller ETT (6.0-7.0), increased aspiration risk\n6. **No modification to medications** — standard ACLS drugs\n\n---\n\n**THE 4-MINUTE RULE:**\n\nIf no ROSC by **4 minutes** and uterus is ≥20 weeks:\n→ **Begin resuscitative hysterotomy**\n→ Goal: delivery by **5 minutes** of arrest\n\n**Purpose:** Relieve aortocaval compression to improve maternal resuscitation.\n\n[Resuscitative Hysterotomy Procedure](#/info/preg-resuscitative-hysterotomy) — step-by-step technique.\n\n**Do NOT move to OR.** Perform at bedside. Continue CPR throughout. [4][9]","citation":[4,9],"next":"preg-trauma-rhyst","calculatorLinks":[{"id":"resuscitative-hysterotomy","label":"Resuscitative Hysterotomy Guide","kind":"tree"}],"summary":"Manual LUD, same defib doses. No ROSC by 4 min + ≥20 weeks = begin resuscitative hysterotomy.","safetyLevel":"critical"}'::jsonb
WHERE id = 'preg-trauma-cardiac-arrest' AND tree_id = 'pregnancy-trauma';

-- Node: rvf-start (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":1,"title":"Refractory VF/VT","body":"**Definition:** VF or pulseless VT persisting after:\n• 3+ defibrillation attempts with 2-minute CPR cycles\n• Standard ACLS interventions (epi, antiarrhythmic)\n\n**2025 AHA terminology:** \"Persisting VF/pVT\" (preferred when mechanism unclear) [1][2]\n\n**Subtypes:**\n| Type | Definition |\n|------|------------|\n| True shock-refractory | VF never terminates |\n| Recurrent VF | VF terminates but refibrillates <5 sec |\n| Electrical storm | 3+ sustained VT/VF in 24h |\n\n**Incidence:** 10-25% of OHCA; survival only 2-12% with standard care [1]\n\n→ [Post-ROSC Management](#/node/rvf-post-rosc) once circulation returns","citation":[1,2],"next":"rvf-optimize","images":[{"src":"images/refractory-vfvt/vf-ecg-tracing.png","alt":"ECG tracing showing ventricular fibrillation","caption":"Ventricular fibrillation: chaotic, disorganized waveform with no discernible QRS complexes. Refractory VF persists after 3+ defibrillation attempts — requires escalation beyond standard ACLS. CC BY-SA 3.0 Wikimedia Commons."}],"calculatorLinks":[{"id":"ecpr-criteria","label":"ECPR Criteria Checklist"},{"id":"vf-dsd","label":"DSD Setup Guide","kind":"info"},{"id":"esmolol-calc","label":"Esmolol Calculator"}],"summary":"VF/pVT persisting after 3+ shocks and ACLS — 10-25% of OHCA, only 2-12% survival with standard care","skippable":true}'::jsonb
WHERE id = 'rvf-start' AND tree_id = 'refractory-vfvt';

-- Node: xyl-start (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"question","module":1,"title":"Xylazine Toxicity — Initial Assessment","body":"**Xylazine Quick Reference** — key facts at a glance.\n\n**What is Xylazine (\"Tranq\")?**\n• **Alpha-2 adrenergic agonist** (same class as clonidine, dexmedetomidine)\n• FDA-approved for veterinary use ONLY — not approved for humans\n\n**The epidemic (2025 update):**\n• **MEDETOMIDINE now dominant** in some markets — detected in **72% of Philadelphia samples** (Oct-Dec 2024), while xylazine dropped from 98% to 31% [8]\n• Medetomidine is **10x more potent** than xylazine — expect more severe sedation and bradycardia\n• Same management principles apply (alpha-2 agonist toxidrome)\n\n**Critical point:** These drugs are **NOT reversed by naloxone** — they are not opioids. However, **still give naloxone** because 95% of exposures involve fentanyl co-ingestion [1][2].\n\nWhat is the patient''s current presentation?","citation":[1,2,8],"options":[{"label":"Acute overdose presentation","description":"Respiratory depression, altered mental status, recent use","next":"xyl-oa2a"},{"label":"Skin wounds present","description":"Necrotic ulcers, non-healing wounds, may or may not be at injection sites","next":"xyl-wound-assess"},{"label":"Withdrawal symptoms","description":"Restless, anxious, tachycardic — recent cessation of use","next":"xyl-withdrawal"}],"calculatorLinks":[{"id":"xyl-wound-staging","label":"Xylazine Wound Staging"},{"id":"xylazine-toxicity","label":"Tranq vs Opioid Withdrawal","kind":"tree","node":"xyl-withdrawal-comparison"}],"summary":"Alpha-2 agonist NOT reversed by naloxone — medetomidine now 72% of Philly supply (10x more potent than xylazine)","safetyLevel":"critical"}'::jsonb
WHERE id = 'xyl-start' AND tree_id = 'xylazine-toxicity';

COMMIT;